insert into public.questions
  (question_text, option_a, option_b, option_c, option_d, correct_option, explanation, category, difficulty, is_active)
select n.question_text, n.option_a, n.option_b, n.option_c, n.option_d,
       n.correct_option, n.explanation, n.category, n.difficulty, true
from new_questions n
where not exists (
  select 1 from public.questions q where q.question_text = n.question_text
);

